      SUBROUTINE CHEK (CKK)CC     LOOKS FOR MAIN BODY OF BENDING MAGNET ASSOCIATED WITH FRINGING FIELDCC     LIST OF COMMON BLOCKSC      LOGICAL         CKKC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'DATA0B.CIN'      INCLUDE 'DATA1A.CIN'      INCLUDE 'DATA2A.CIN'      INCLUDE 'ELM2B.CIN'      INCLUDE 'ELM2D.CIN'      INCLUDE 'ELM4E.CIN'      INCLUDE 'INDPAR.CIN'      INCLUDE 'IOUNIT.CIN'CC     LOCAL VARIABLESC      INTEGER         IDATA, II, IL, IADR, J, K, NBVARY, TYPEN      EXTERNAL        IDATACC-----------------------------------------------------------------      CKK = .TRUE.CC     CHECK TO SEE IF INTERVENING CARDS ARE I/O CONTROLSC     AND DECIDE IF FRINGING FIELD IS AT ENTRANCE OR EXITC      J = NUM      DO 10 K = 1, 100      J = J + NDIF      IF (J .LE. 0) GO TO 20      IF (J .GT. NEL) GO TO 20      II = ISTOR(J)      TYPEN = IDATA(II)      IF (TYPEN .EQ. 4) GO TO 50      IF (TYPEN .NE. 13 .AND. TYPEN .NE. 23 .AND. TYPEN .NE. 30)     1    GO TO 20   10 CONTINUEC   20 J = NUM      DO 30 K = 1, 100      J = J - NDIF      IF (J .LE. 0) GO TO 40      IF (J .GT. NEL) GO TO 40      II = ISTOR(J)      TYPEN = IDATA(II)      IF (TYPEN .EQ. 4) GO TO 60      IF (TYPEN .NE. 13 .AND. TYPEN .NE. 23 .AND. TYPEN .NE. 30)     1    GO TO 40   30 CONTINUE   40 WRITE (NOUT, 140)  140 FORMAT ('0*** BEND ELEMENT NOT FOUND FOR ROTAT ELEMENT')      CKK = .FALSE.      RETURNCC     SET FRINGING FIELD PARAMETERSC     FRINGING FIELD IS AT MAGNET ENTRANCEC   50 BEFORE = .TRUE.      NUM4 = J      FFIN = .TRUE.      GO TO 70CC     FRINGING FIELD IS AT MAGNET EXITC   60 BEFORE = .FALSE.CC     FIND VARY CODE OF FIELD FOR USE IN FITTINGC   70 IL = IPTOJB(1)      IF (IL .EQ. 0) IADR = II + 1      IF (IL .NE. 0) IADR = II + 2   80 IBVARY = IADR      NBVARY = TIE(IBVARY)      IF (NBVARY .EQ. 100) THEN        IADR = IDATA(IADR)        GO TO 80      ENDIF      RETURN      END